     1→import { Block, Screen, Text } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import { MatrixService } from "modules/matrix-client/services";
     4→import { addDateDividers, getEventId } from "modules/matrix-client/utils";
     5→import { useEffect, useMemo, useRef, useState } from "react";
     6→import {
     7→  ActivityIndicator,
     8→  FlatList,
     9→  Image,
    10→  KeyboardAvoidingView,
    11→  type NativeScrollEvent,
    12→  type NativeSyntheticEvent,
    13→  StyleSheet,
    14→} from "react-native";
    15→import { useSafeAreaInsets } from "react-native-safe-area-context";
    16→import { Button, Loading } from "shared/components";
    17→import { Colors } from "shared/styles";
    18→import {
    19→  DateDivider,
    20→  RoomHeader,
    21→  RoomInput,
    22→  SingleMessageType,
    23→} from "./fragments";
    24→import { useRoomInitialization, useRoomTimeline } from "./hooks";
    25→import { filterSameStateKey, handleIsPreviousSameSender } from "./utils";
    26→
    27→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
    28→  route,
    29→  navigation,
    30→}) => {
    31→  const { roomId } = route.params;
    32→  const client = MatrixService.instance;
    33→  const room = client?.getRoom(roomId);
    34→  const insets = useSafeAreaInsets();
    35→  const flatListRef = useRef<FlatList>(null);
    36→  /* Track whether list is scrolled to bottom */
    37→  const isAtBottomRef = useRef(true);
    38→  const [showScrollDown, setShowScrollDown] = useState(false);
    39→  const hasActiveCall = room?.hasActiveRoomCall();
    40→
    41→  const {
    42→    events,
    43→    loadingMessage,
    44→    refreshing,
    45→    updateTrigger,
    46→    loadMoreMessages,
    47→    markAsRead,
    48→  } = useRoomTimeline({ room, roomId });
    49→
    50→  const { roomMembers, hasNoCallOption } = useRoomInitialization({ room });
    51→
    52→  const sortedEvents = useMemo(() => {
    53→    const sorted = [...events].sort(
    54→      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    55→    );
    56→
    57→    return filterSameStateKey(sorted);
    58→  }, [events]);
    59→
    60→  /**Events with date dividers */
    61→  const eventsWithDividers = useMemo(() => {
    62→    return addDateDividers(sortedEvents);
    63→  }, [sortedEvents]);
    64→
    65→  const handleLoadMore = async () => {
    66→    setShowScrollDown(false);
    67→    await loadMoreMessages();
    68→  };
    69→
    70→  const handleScrollDown = () => {
    71→    flatListRef.current?.scrollToEnd({ animated: true });
    72→    setShowScrollDown(false);
    73→  };
    74→
    75→  const handleOnScroll = ({
    76→    nativeEvent,
    77→  }: NativeSyntheticEvent<NativeScrollEvent>) => {
    78→    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
    79→    const paddingToBottom = 100;
    80→    const atBottom =
    81→      layoutMeasurement.height + contentOffset.y >=
    82→      contentSize.height - paddingToBottom;
    83→    isAtBottomRef.current = atBottom;
    84→    if (!atBottom) return;
    85→    setShowScrollDown(false);
    86→    markAsRead();
    87→  };
    88→
    89→  // Show scroll down button if not at bottom and not own message
    90→  useEffect(() => {
    91→    if (isAtBottomRef.current || sortedEvents[0]?.isOwn) return;
    92→
    93→    setShowScrollDown(true);
    94→  }, [sortedEvents]);
    95→
    96→  const handleStartCall = () => {
    97→    if (!client || !room) {
    98→      console.error("Client or room not available");
    99→      return;
   100→    }
   101→
   102→    navigation.navigate("elementCall", {
   103→      roomId,
   104→      roomName: room.displayName(),
   105→    });
   106→  };
   107→
   108→  console.log(sortedEvents);
   109→
   110→  if (!room) return null;
   111→
   112→  return (
   113→    <Screen hideTopSafeArea scrollable={false}>
   114→      <RoomHeader
   115→        room={room}
   116→        roomMembers={roomMembers}
   117→        hasActiveCall={hasActiveCall ?? false}
   118→        hasNoCallOption={hasNoCallOption}
   119→        topInset={insets.top}
   120→        onBack={() => navigation.goBack()}
   121→        onRoomDetails={() => navigation.navigate("roomDetails", { room })}
   122→        onStartCall={handleStartCall}
   123→      />
   124→
   125→      {loadingMessage ? (
   126→        <Loading />
   127→      ) : (
   128→        <KeyboardAvoidingView style={{ flex: 1 }} behavior="padding">
   129→          {refreshing && (
   130→            <Block align="center" justify="center" width="100%" paddings={40}>
   131→              <ActivityIndicator size="large" color={Colors.primary} />
   132→            </Block>
   133→          )}
   134→          <FlatList
   135→            ref={flatListRef}
   136→            data={eventsWithDividers}
   137→            keyExtractor={(item) => {
   138→              if (item.type === "divider") return item.id;
   139→
   140→              return getEventId(item.data) ?? "";
   141→            }}
   142→            extraData={updateTrigger}
   143→            contentContainerStyle={styles.listContent}
   144→            onContentSizeChange={() => {
   145→              if (!isAtBottomRef.current) return;
   146→              // Auto-scroll only if already at the bottom
   147→              flatListRef.current?.scrollToEnd({ animated: false });
   148→            }}
   149→            onRefresh={handleLoadMore}
   150→            refreshing={refreshing}
   151→            onScroll={handleOnScroll}
   152→            renderItem={({ item }) => {
   153→              if (item.type === "divider") {
   154→                return <DateDivider date={item.date} />;
   155→              }
   156→
   157→              // For events, calculate the index in the original sortedEvents array
   158→              const eventIndex = sortedEvents.findIndex(
   159→                (e) => getEventId(e) === getEventId(item.data),
   160→              );
   161→
   162→              return (
   163→                <SingleMessageType
   164→                  event={item.data}
   165→                  isPreviousSameSender={handleIsPreviousSameSender(
   166→                    sortedEvents,
   167→                    item.data,
   168→                    eventIndex,
   169→                  )}
   170→                />
   171→              );
