      />
      <Block
        background="transparent"
        border={{
          borderRadius: 12,
        }}
        align="center"
        overflow="hidden"
        width={targetWidth}
        height={targetHeight}
        onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
      >
        {isLoading ? (
          <Block
            width="100%"
            height="100%"
            background={Colors.white20}
            align="center"
            justify="center"
          >
            <Loading isFullScreen={false} />
          </Block>
        ) : uri ? (
          <Video
            source={{ uri }}
            style={{
              width: targetWidth,
              height: targetHeight,
            }}
            resizeMode="contain"
            controls
            paused
          />
        ) : null}
      </Block>
      <Block
        align={isUser ? "flex-end" : "flex-start"}
        margins={{ marginTop: 12 }}
      >
        {caption ? (
          <Block
            paddings={12}
            background={isUser ? Colors.primary : Colors.message}
            border={{
              borderRadius: 24,
            }}
            flexDirection={isUser ? "row-reverse" : "row"}
            gap={{
              row: 4,
              col: 16,
            }}
            align="center"
            flex={{ flexWrap: "wrap" }}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
          >
            <Text size={TextSize.small} color="white" font="Gridlite-PEVFTRIAL">
              {caption}
            </Text>
            <Text size={TextSize.tiny} color={Colors.white50}>
              {format(Number(event.timestamp), "HH:mm")}
            </Text>
          </Block>
        ) : (
          <Text size={TextSize.tiny} color={Colors.white50}>
            {format(Number(event.timestamp), "HH:mm")}
          </Text>
        )}
      </Block>
      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
    </Block>
  );
};

