import {
  type EventTimelineItem,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";

export const getLastMessageType = (
  event: EventTimelineItem | undefined,
): string => {
  const type = event?.content.tag;
  const senderName = event?.isOwn
    ? "You"
    : event?.senderProfile?.tag === "Ready"
      ? event?.senderProfile?.inner?.displayName || "Unknown"
      : "Unknown";

  if (
    type === TimelineItemContent_Tags.CallInvite ||
    type === TimelineItemContent_Tags.RtcNotification
  ) {
    return `${senderName}: 🔔 Call notify`;
  }

  if (type === TimelineItemContent_Tags.MsgLike) {
    const kind = event?.content.inner.content.kind;
    let messageBody = "";

    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;

      if (msgType?.tag === MessageType_Tags.Text) {
        messageBody = kind.inner.content.body || "";
      } else if (msgType?.tag === MessageType_Tags.Image) {
        messageBody = "📷 Image";
      } else if (msgType?.tag === MessageType_Tags.File) {
        messageBody = "📎 File";
      } else if (msgType?.tag === MessageType_Tags.Video) {
        messageBody = "🎥 Video";
      } else if (msgType?.tag === MessageType_Tags.Audio) {
        messageBody = "🎵 Audio";
      } else {
        messageBody = "Message";
      }
    }

    return `${senderName}: ${messageBody}`;
  }

  if (type === TimelineItemContent_Tags.RoomMembership) {
    return `${senderName}: Room name changed`;
  }

  if (type === TimelineItemContent_Tags.ProfileChange) {
    return `${senderName}: Personal settings changed`;
  }

  return "Unknown message type";
};

