import { Block, Text } from "@prototyp/skeletor";
import type {
  AudioMessageContent,
  EventTimelineItem,
  UserProfile,
} from "@unomed/react-native-matrix-sdk";
import { format } from "date-fns";
import { MatrixService } from "modules/matrix-client/services";
import { useAudioPlayback } from "modules/recorder-player/hooks";
import type { FC } from "react";
import { useEffect, useState } from "react";
import { Image, StyleSheet } from "react-native";
import Toast from "react-native-toast-message";
import { Button, Loading, SeenBy } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { MessageSender } from "../message-sender";

interface Props {
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
  content: AudioMessageContent;
}

function formatDuration(milliseconds: number) {
  const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
}

export const VoiceMessage: FC<Props> = ({
  event,
  isPreviousSameSender,
  content,
}) => {
  const eventId =
    "inner" in event.eventOrTransactionId
      ? "eventId" in event.eventOrTransactionId.inner
        ? event.eventOrTransactionId.inner.eventId
        : event.eventOrTransactionId.inner.transactionId
      : String(event.timestamp);
  const [messageWidth, setMessageWidth] = useState(40);
  const [isLoading, setIsLoading] = useState(false);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const duration = content.info?.duration ?? 0;
  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
  const { isPlaying, currentMs, play, pause, resume } =
    useAudioPlayback(eventId);

  useEffect(() => {
    MatrixService.getReadReceipts(event)
      .then((users) => {
        setSeenBy(users);
      })
      .catch((error) => {
        console.error("Failed to get read receipt users:", error);
        setSeenBy([]);
      });
  }, [event]);

  const onTogglePlay = async () => {
    //For these types of voice messages, we need to convert them to m4a with ffmpeg
    if (["audio/ogg", "audio/opus"].includes(content.info?.mimetype ?? "")) {
      Toast.show({
        type: "error",
        text1: "This voice message is not supported on this device.",
      });
      return;
    }

    try {
      setIsLoading(true);

      if (isPlaying) {
        await pause();
        return;
      }

      // If paused mid-track and not at the end, resume instead of restarting
      if (currentMs > 0 && currentMs < duration) {
        await resume();
        return;
      }

      // Re-fetch the playback URL to ensure it's valid (temp files may be cleaned up)
      if (!content.source || !MatrixService.instance) {
        Toast.show({
          type: "error",
          text1: "Failed to fetch voice message.",
        });
        return;
      }

      const mediaHandle = await MatrixService.instance.getMediaFile(
        content.source,
        `voice-${eventId}.${content.info?.mimetype?.split("/")[1] ?? "m4a"}`,
        content.info?.mimetype || "audio/m4a",
        true, // useCache
        undefined,
      );

      const filePath = mediaHandle.path();
      const freshUrl = filePath.startsWith("file://")
        ? filePath
        : `file://${filePath}`;

      await play(freshUrl, duration);
    } catch (e) {
      Toast.show({
        type: "error",
        text1: "Failed to play voice message.",
      });
      console.log(e);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        isUser={isUser}
        senderId={senderId}
        isPreviousSameSender={isPreviousSameSender}
      />
      <Block
        paddings={12}
        background={isUser ? Colors.primary : Colors.message}
        border={{
          borderRadius: 24,
        }}
        flexDirection={isUser ? "row-reverse" : "row"}
        gap={{
          row: 8,
          col: 16,
        }}
        align="center"
        onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
      >
        <Button.Wrapper
          disabled={isLoading}
          onPress={onTogglePlay}
          style={styles.playButton}
        >
          {isLoading ? (
            <Loading isFullScreen={false} />
          ) : (
            <Image
              source={
                isPlaying
                  ? require("assets/icons/pause-big.png")
                  : require("assets/icons/play.png")
              }
              tintColor={Colors.white}
            />
          )}
        </Button.Wrapper>
        <Block flex={1} gap={4}>
          <Block
            height={4}
            background={Colors.white20}
            border={{ borderRadius: 2 }}
          >
            <Block
              height={4}
              width={`${Math.min(100, Math.round((currentMs / duration) * 100))}%`}
              background={Colors.white50}
              border={{ borderRadius: 2 }}
            />
          </Block>
          <Block flexDirection="row" justify="space-between">
            <Text size={TextSize.tiny} color={Colors.white80}>
              {formatDuration(currentMs)}
            </Text>
            <Text size={TextSize.tiny} color={Colors.white50}>
              {formatDuration(duration)}
            </Text>
          </Block>
        </Block>
        <Text size={TextSize.tiny} color={Colors.white50}>
          {format(Number(event.timestamp), "HH:mm")}
        </Text>
      </Block>
      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
    </Block>
  );
};

const styles = StyleSheet.create({
  playButton: {
    width: 40,
    height: 40,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: Colors.white20,
    borderRadius: 20,
  },
});

/**
 * Paginate backwards, whether we are in focused mode or in live mode.
 *
 * Returns whether we hit the start of the timeline or not.
 */
paginateBackwards(numEvents: number, asyncOpts_?: {
    signal: AbortSignal;
}): Promise<boolean>;
/**
 * Paginate forwards, whether we are in focused mode or in live mode.
 *
 * Returns whether we hit the end of the timeline or not.
 */
paginateForwards(numEvents: number, asyncOpts_?: {
    signal: AbortSignal;
}): Promise<boolean>;
/**
 * Adds a new pinned event by sending an updated `m.room.pinned_events`
 * event containing the new event id.
 *
 * Returns `true` if we sent the request, `false` if the event was already
 * pinned.
 */
pinEvent(eventId: string, asyncOpts_?: {
    signal: AbortSignal;
}): Promise<boolean>;
/**
 * Redacts an event from the timeline.
 *
 * Only works for events that exist as timeline items.
 *
 * If it was a local event, this will *try* to cancel it, if it was not
 * being sent already. If the event was a remote event, then it will be
